-- BACKLOG-4263 sync 2.49, P9 (T-S) harness helpers. Loaded inside the one call (which ends in RAISE, so nothing persists).
-- Every id is made at run time (gen_random_uuid); every name, address and secret is invented ('@example.test').
CREATE TEMP TABLE t_out (k text PRIMARY KEY, v jsonb) ON COMMIT DROP;
CREATE TEMP TABLE t_fx (k text PRIMARY KEY, v uuid) ON COMMIT DROP;
CREATE TEMP TABLE t_txt (k text PRIMARY KEY, v text) ON COMMIT DROP;
CREATE FUNCTION pg_temp.rec(k text, v jsonb) RETURNS void LANGUAGE sql AS $h$
  INSERT INTO pg_temp.t_out VALUES (k, v) ON CONFLICT (k) DO UPDATE SET v = excluded.v
$h$;
CREATE FUNCTION pg_temp.f(k text) RETURNS uuid LANGUAGE sql STABLE AS $h$ SELECT v FROM pg_temp.t_fx WHERE t_fx.k = f.k $h$;
CREATE FUNCTION pg_temp.s(k text) RETURNS text LANGUAGE sql STABLE AS $h$ SELECT v::text FROM pg_temp.t_fx WHERE t_fx.k = s.k $h$;
CREATE FUNCTION pg_temp.put(k text, v uuid) RETURNS uuid LANGUAGE sql AS $h$
  INSERT INTO pg_temp.t_fx VALUES (k, v) ON CONFLICT (k) DO UPDATE SET v = excluded.v RETURNING v
$h$;
CREATE FUNCTION pg_temp.tx(k text) RETURNS text LANGUAGE sql STABLE AS $h$ SELECT v FROM pg_temp.t_txt WHERE t_txt.k = tx.k $h$;
CREATE FUNCTION pg_temp.h(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$ SELECT encode(sha256(convert_to(t, 'UTF8')), 'hex') $h$;
CREATE FUNCTION pg_temp.j(t text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $h$
BEGIN RETURN t::jsonb; EXCEPTION WHEN OTHERS THEN RETURN to_jsonb(t); END $h$;
CREATE FUNCTION pg_temp.pass(c boolean, detail text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$
  SELECT CASE WHEN coalesce(c, false) THEN 'PASS' ELSE 'FAIL: ' || coalesce(left(detail, 900), '-') END
$h$;
CREATE FUNCTION pg_temp.clear_claims() RETURNS void LANGUAGE plpgsql AS $h$
BEGIN
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('request.jwt.claim.sub', '', true);
  PERFORM set_config('request.jwt.claim.role', '', true);
END $h$;
-- One SELECT as an API role with the user's claims (own subtransaction). Returns its single value as text, or
-- 'ERR <sqlstate> <message>'.
CREATE FUNCTION pg_temp.call_as(u uuid, q text, r text) RETURNS text LANGUAGE plpgsql AS $h$
DECLARE j jsonb;
BEGIN
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', u, 'role', r)::text, true);
    PERFORM set_config('request.jwt.claim.sub', coalesce(u::text, ''), true);
    PERFORM set_config('request.jwt.claim.role', r, true);
    EXECUTE format('SET LOCAL ROLE %I', r);
    EXECUTE q INTO j;
    EXECUTE 'RESET ROLE';
    PERFORM pg_temp.clear_claims();
    RETURN coalesce(j::text, 'null');
  EXCEPTION WHEN OTHERS THEN
    EXECUTE 'RESET ROLE';
    PERFORM pg_temp.clear_claims();
    RETURN 'ERR ' || SQLSTATE || ' ' || left(SQLERRM, 200);
  END;
END $h$;
-- public.<fn>(args) as fixture user k (authenticated); args is a format() list of %L placeholders.
CREATE FUNCTION pg_temp.as_user(k text, fn text, args text, VARIADIC vals text[]) RETURNS jsonb LANGUAGE plpgsql AS $h$
BEGIN
  RETURN pg_temp.j(pg_temp.call_as(pg_temp.f(k), format('SELECT to_jsonb(public.' || quote_ident(fn) || '(' || args || '))', VARIADIC vals), 'authenticated'));
END $h$;

-- MCP fixtures: the portal secret sits in mcp_settings.portal_secret_prev_sha256 for this call only.
CREATE FUNCTION pg_temp.secret() RETURNS text LANGUAGE sql STABLE AS $h$ SELECT 'p4263t-portal-secret-' || pg_temp.s('RUN') $h$;
CREATE FUNCTION pg_temp.res() RETURNS text LANGUAGE sql IMMUTABLE AS $h$ SELECT 'https://p4263t-fixture.example.test/api/mcp' $h$;
CREATE FUNCTION pg_temp.dg(k text) RETURNS bytea LANGUAGE sql STABLE AS $h$ SELECT sha256(convert_to('p4263t-at-' || pg_temp.s('RUN') || k, 'UTF8')) $h$;
CREATE FUNCTION pg_temp.client() RETURNS text LANGUAGE sql STABLE AS $h$ SELECT 'kpr_c_' || substr(md5('p4263t-client-' || pg_temp.s('RUN')), 1, 22) $h$;
-- an active connection of user u approved on approval-page version nv, with an access token
CREATE FUNCTION pg_temp.conn(k text, u uuid, nv int) RETURNS uuid LANGUAGE plpgsql AS $h$
DECLARE v uuid := pg_temp.put(k, gen_random_uuid());
BEGIN
  INSERT INTO public.mcp_connections (id, user_id, client_id, provider, client_name, redirect_uri, resource, scope, notice_version, status, activated_at)
  VALUES (v, u, pg_temp.client(), 'anthropic', 'Fixture app ' || k, 'https://claude.ai/api/mcp/auth_callback', pg_temp.res(), 'mcp:read', nv, 'active', now());
  INSERT INTO public.mcp_tokens (token_sha256, connection_id, kind, pepper_version, expires_at)
  VALUES (sha256(pg_temp.dg(k)), v, 'access', (SELECT pepper_version FROM public.mcp_settings WHERE id), now() + interval '1 hour');
  RETURN v;
END $h$;
-- A tool call as the portal does it (anon role, portal secret, token digest of connection k). The fixture users' and
-- the connection's per-minute counters are cleared first, so repeated calls in one run are not rate limited. Returns
-- the answer text or 'ERR <sqlstate> <message>'.
CREATE FUNCTION pg_temp.tool(fn text, k text, extra text) RETURNS text LANGUAGE plpgsql AS $h$
BEGIN
  DELETE FROM public.mcp_rate_counters
   WHERE bucket IN ('call_conn:' || pg_temp.s(k), 'call_user:' || pg_temp.s('A'), 'call_user:' || pg_temp.s('B'));
  RETURN pg_temp.call_as(NULL, format('SELECT public.%I(%L, %L::bytea, %L%s)', fn, pg_temp.secret(), pg_temp.dg(k), pg_temp.res(),
                                       CASE WHEN extra = '' THEN '' ELSE ', ' || extra END), 'anon');
END $h$;
CREATE FUNCTION pg_temp.lst(k text, deal text, channel text, review text, lim int, cursor text) RETURNS jsonb LANGUAGE sql AS $h$
  SELECT pg_temp.j(pg_temp.tool('mcp_list_deal_messages', k, format('%L, %L, %L, %L::integer, %L', deal, channel, review, lim, cursor)))
$h$;
CREATE FUNCTION pg_temp.getm(k text, msg text, part int) RETURNS jsonb LANGUAGE sql AS $h$
  SELECT pg_temp.j(pg_temp.tool('mcp_get_message', k, format('%L, %L::integer', msg, part)))
$h$;
CREATE FUNCTION pg_temp.access(k text) RETURNS jsonb LANGUAGE sql AS $h$
  SELECT pg_temp.j(pg_temp.tool('mcp_message_access', k, ''))
$h$;
-- reads and last_outcome are VOLATILE: a STABLE function reads with the snapshot of the statement that calls it, so in
-- an expression that also makes a tool call it would not see the rows that call wrote
CREATE FUNCTION pg_temp.reads(u text) RETURNS bigint LANGUAGE sql VOLATILE AS $h$
  SELECT count(*) FROM public.mcp_message_reads WHERE user_id = pg_temp.f(u)
$h$;
CREATE FUNCTION pg_temp.last_outcome(k text) RETURNS text LANGUAGE sql VOLATILE AS $h$
  SELECT outcome FROM public.mcp_call_log WHERE connection_id = pg_temp.f(k) ORDER BY id DESC LIMIT 1
$h$;
-- message ids of every page of list_deal_messages on one deal, walked with the cursor (at most 200 pages)
CREATE FUNCTION pg_temp.walk(k text, deal text, lim int) RETURNS jsonb LANGUAGE plpgsql AS $h$
DECLARE r jsonb; c text; ids jsonb := '[]'; n int := 0; maxb int := 0;
BEGIN
  LOOP
    r := pg_temp.lst(k, deal, NULL, NULL, lim, c);
    IF r ->> 'ok' IS DISTINCT FROM 'true' THEN
      RETURN jsonb_build_object('error', r, 'pages', n);
    END IF;
    maxb := greatest(maxb, octet_length(r::text));
    ids := ids || coalesce((SELECT jsonb_agg(e -> 'message_id') FROM jsonb_array_elements(r -> 'result' -> 'messages') e), '[]');
    n := n + 1;
    c := r -> 'result' -> 'page' ->> 'next_cursor';
    EXIT WHEN c IS NULL OR n >= 200;
  END LOOP;
  RETURN jsonb_build_object('ids', ids, 'pages', n, 'max_bytes', maxb);
END $h$;
-- every part of get_message, joined; checks each answer's size
CREATE FUNCTION pg_temp.all_parts(k text, msg text) RETURNS jsonb LANGUAGE plpgsql AS $h$
DECLARE r jsonb; body text := ''; p int := 1; parts int; maxb int := 0; bad jsonb := '[]';
BEGIN
  LOOP
    r := pg_temp.getm(k, msg, p);
    IF r ->> 'ok' IS DISTINCT FROM 'true' THEN
      RETURN jsonb_build_object('error', r, 'part', p);
    END IF;
    maxb := greatest(maxb, octet_length(r::text));
    IF octet_length((r -> 'result')::text) > 90000 THEN bad := bad || to_jsonb(p); END IF;
    body := body || coalesce(r -> 'result' -> 'message' ->> 'body_text', '');
    parts := (r -> 'result' -> 'message' ->> 'parts')::int;
    IF (r -> 'result' -> 'message' ->> 'part')::int IS DISTINCT FROM p THEN
      RETURN jsonb_build_object('error', 'part number', 'part', p);
    END IF;
    EXIT WHEN p >= parts OR p >= 1000;
    p := p + 1;
  END LOOP;
  RETURN jsonb_build_object('parts', parts, 'max_bytes', maxb, 'over_cap', bad, 'body_md5', md5(body),
                            'after_last', pg_temp.getm(k, msg, parts + 1));
END $h$;
-- mutants: a reader is replaced as its owner (mcp_reader), as the migration creates it
CREATE FUNCTION pg_temp.as_reader(q text) RETURNS void LANGUAGE plpgsql AS $h$
BEGIN
  GRANT CREATE ON SCHEMA public TO mcp_reader;
  SET LOCAL ROLE mcp_reader;
  EXECUTE q;
  RESET ROLE;
  REVOKE CREATE ON SCHEMA public FROM mcp_reader;
END $h$;

-- desktop rows, in the shape the desktop's projection sends (jcsProjection-4243.test.ts:47) and cloud_upsert_messages
-- reads (20261123100000 cloud_upsert_messages): participants {from: string, to: [string], cc: [string]}
CREATE FUNCTION pg_temp.mrow(lid text, kind text, subject text, body text, people jsonb, sent text, recv text,
                             match_reason text, hidden boolean, thread text) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $h$
  SELECT jsonb_build_object('local_id', lid, 'local_link_id', 'cm-' || lid, 'content_hash', pg_temp.h('m:' || lid || coalesce(body, '')),
    'channel_kind', kind, 'channel', CASE WHEN kind = 'text' THEN 'imessage' ELSE 'email' END, 'direction', 'inbound',
    'subject', subject, 'body_text', body, 'participants', people, 'thread_key', thread, 'sent_at', sent, 'received_at', recv,
    'link_source', 'auto', 'link_confidence', CASE WHEN match_reason = 'address_missing' THEN 0.5 ELSE 1 END,
    'match_reason', match_reason, 'linked_at', NULL, 'link_origin', 'link', 'hidden_from_export', hidden, 'source_updated_at', NULL)
$h$;
CREATE FUNCTION pg_temp.frow(lid text, msg text, name text, mime text, reason text) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $h$
  SELECT jsonb_build_object('local_id', lid, 'content_hash', pg_temp.h('f:' || lid), 'filename', name, 'mime_type', mime,
    'size_bytes', 60000000, 'not_saved_reason', reason, 'message_local_id', msg, 'message_channel_kind', CASE WHEN msg IS NULL THEN NULL ELSE 'email' END)
$h$;
CREATE FUNCTION pg_temp.msgs(u text, inst text, deal text, rows jsonb) RETURNS jsonb LANGUAGE plpgsql AS $h$
DECLARE r jsonb := pg_temp.as_user(u, 'cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s(u), pg_temp.s(inst), pg_temp.s(deal), rows::text);
BEGIN
  IF r ->> 'ok' IS DISTINCT FROM 'true' OR EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'results') e WHERE e ->> 'status' <> 'applied') THEN
    RAISE EXCEPTION 'FIXTURE messages on % failed: %', deal, left(r::text, 400);
  END IF;
  PERFORM pg_temp.put(e ->> 'local_id', (e ->> 'cloud_id')::uuid) FROM jsonb_array_elements(r -> 'results') e;
  RETURN r;
END $h$;
CREATE FUNCTION pg_temp.files(u text, inst text, deal text, rows jsonb) RETURNS jsonb LANGUAGE plpgsql AS $h$
DECLARE r jsonb := pg_temp.as_user(u, 'cloud_upsert_files', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s(u), pg_temp.s(inst), pg_temp.s(deal), rows::text);
BEGIN
  IF r ->> 'ok' IS DISTINCT FROM 'true' OR EXISTS (SELECT 1 FROM jsonb_array_elements(r -> 'results') e WHERE e ->> 'status' <> 'applied') THEN
    RAISE EXCEPTION 'FIXTURE files on % failed: %', deal, left(r::text, 400);
  END IF;
  PERFORM pg_temp.put(e ->> 'local_id', (e ->> 'cloud_id')::uuid) FROM jsonb_array_elements(r -> 'results') e;
  RETURN r;
END $h$;
CREATE FUNCTION pg_temp.deal(u text, inst text, k text, status text) RETURNS uuid LANGUAGE plpgsql AS $h$
DECLARE r jsonb := pg_temp.as_user(u, 'cloud_upsert_deal', '%L::uuid, %L::jsonb', pg_temp.s(u),
          jsonb_build_object('source_install_id', pg_temp.s(inst), 'local_id', 'p4263t-' || k, 'content_hash', pg_temp.h('d:' || k),
                             'property_address', 'Fixture ' || k || ' Street', 'status', status)::text);
BEGIN
  IF r -> 'results' -> 0 ->> 'status' IS DISTINCT FROM 'applied' THEN RAISE EXCEPTION 'FIXTURE deal % failed: %', k, left(r::text, 400); END IF;
  RETURN pg_temp.put(k, (r -> 'results' -> 0 ->> 'cloud_id')::uuid);
END $h$;
CREATE FUNCTION pg_temp.tomb(u text, inst text, kind text, ids uuid[]) RETURNS jsonb LANGUAGE sql AS $h$
  SELECT pg_temp.as_user(u, 'cloud_tombstone', '%L::uuid, %L::uuid, %L, %L::uuid[]', pg_temp.s(u), pg_temp.s(inst), kind, ids::text)
$h$;
CREATE FUNCTION pg_temp.claim(u text, inst text, rep boolean) RETURNS jsonb LANGUAGE sql AS $h$
  SELECT pg_temp.as_user(u, 'cloud_claim_install', '%L::uuid, %L::uuid, %L::boolean', pg_temp.s(u), pg_temp.s(inst), rep::text)
$h$;
CREATE FUNCTION pg_temp.ids(VARIADIC ks text[]) RETURNS jsonb LANGUAGE sql STABLE AS $h$
  SELECT coalesce(jsonb_agg(to_jsonb(pg_temp.s(k)) ORDER BY pg_temp.s(k)), '[]') FROM unnest(ks) k
$h$;
CREATE FUNCTION pg_temp.sorted(a jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $h$
  SELECT coalesce(jsonb_agg(e ORDER BY e #>> '{}'), '[]') FROM jsonb_array_elements(a) e
$h$;

-- BACKLOG-4265 harness helpers (loaded after backlog-4263-sync2-t/lib/helpers.sql, whose rec, put, s, f, j, pass,
-- call_as, clear_claims, as_user, getm and lst they use). Inside the one call, which ends in RAISE.
CREATE TEMP TABLE t65_rel (blk text NOT NULL, name text PRIMARY KEY, kind "char" NOT NULL) ON COMMIT DROP;
INSERT INTO pg_temp.t65_rel VALUES
  ('A', 'cloud_deal_messages', 'r'), ('A', 'cloud_deal_files', 'r'), ('A', 'cloud_blobs', 'r'),
  ('B', 'mcp_settings', 'r'), ('B', 'mcp_redirect_allowlist', 'r'), ('B', 'mcp_oauth_clients', 'r'),
  ('B', 'mcp_authorization_requests', 'r'), ('B', 'mcp_connections', 'r'), ('B', 'mcp_authorization_codes', 'r'),
  ('B', 'mcp_tokens', 'r'), ('B', 'mcp_rate_counters', 'r'), ('B', 'mcp_call_log', 'r'), ('B', 'mcp_call_log_id_seq', 'S'),
  ('C', 'cloud_deals', 'r'), ('C', 'cloud_deal_parties', 'r'), ('C', 'cloud_deal_checklists', 'r'),
  ('C', 'cloud_deal_checklist_items', 'r'), ('C', 'cloud_autosave_settings', 'r'), ('C', 'member_addons', 'r');
CREATE TEMP TABLE t65_txt (k text PRIMARY KEY, v text NOT NULL) ON COMMIT DROP;
CREATE FUNCTION pg_temp.tx65(k text) RETURNS text LANGUAGE sql STABLE AS $h$ SELECT v FROM pg_temp.t65_txt WHERE t65_txt.k = tx65.k $h$;
-- the table privilege types of this server (MAINTAIN from PostgreSQL 17)
CREATE FUNCTION pg_temp.privs65() RETURNS text[] LANGUAGE sql STABLE AS $h$
  SELECT ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER']
         || CASE WHEN current_setting('server_version_num')::int >= 170000 THEN ARRAY['MAINTAIN'] ELSE ARRAY[]::text[] END
$h$;
-- the sorted service_role ACL items of relation n: grantor:privilege:grantable,...
CREATE FUNCTION pg_temp.sr_acl65(n text) RETURNS text LANGUAGE sql VOLATILE AS $h$
  SELECT coalesce(string_agg(pg_catalog.pg_get_userbyid(a.grantor)::text || ':' || a.privilege_type || ':' || a.is_grantable::text, ','
                             ORDER BY a.privilege_type COLLATE "C", pg_catalog.pg_get_userbyid(a.grantor)::text COLLATE "C"), '')
    FROM pg_catalog.pg_class c, aclexplode(c.relacl) a
   WHERE c.oid = pg_catalog.to_regclass('public.' || n) AND a.grantee = 'service_role'::regrole
$h$;
-- the ACL items (table and column) of every role except service_role on the 19 relations, as one md5
CREATE FUNCTION pg_temp.other_acl65() RETURNS text LANGUAGE sql VOLATILE AS $h$
  SELECT md5(coalesce(string_agg(z.s, '|' ORDER BY z.s COLLATE "C"), '')) FROM (
    SELECT x.name || '::' || CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee)::text END || ':'
           || pg_catalog.pg_get_userbyid(a.grantor)::text || ':' || a.privilege_type || ':' || a.is_grantable::text AS s
      FROM pg_temp.t65_rel x JOIN pg_catalog.pg_class c ON c.oid = pg_catalog.to_regclass('public.' || x.name)
      CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE a.grantee IS DISTINCT FROM 'service_role'::regrole
    UNION ALL
    SELECT x.name || ':' || t.attname::text || ':' || CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee)::text END || ':'
           || pg_catalog.pg_get_userbyid(a.grantor)::text || ':' || a.privilege_type || ':' || a.is_grantable::text
      FROM pg_temp.t65_rel x JOIN pg_catalog.pg_class c ON c.oid = pg_catalog.to_regclass('public.' || x.name)
      JOIN pg_catalog.pg_attribute t ON t.attrelid = c.oid AND t.attnum > 0 AND NOT t.attisdropped
      CROSS JOIN LATERAL aclexplode(t.attacl) a WHERE a.grantee IS DISTINCT FROM 'service_role'::regrole) z
$h$;
-- the non-owner, non-service_role ACL items of relation n: grantee:privilege,...
CREATE FUNCTION pg_temp.api_acl65(n text) RETURNS text LANGUAGE sql VOLATILE AS $h$
  SELECT coalesce(string_agg(CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee)::text END || ':' || a.privilege_type, ','
                             ORDER BY 1), '')
    FROM pg_catalog.pg_class c, aclexplode(c.relacl) a
   WHERE c.oid = pg_catalog.to_regclass('public.' || n) AND a.grantee IS DISTINCT FROM c.relowner AND a.grantee IS DISTINCT FROM 'service_role'::regrole
$h$;
-- EXECUTE grants of every public function whose source names one of the 19 relations or a message reader, as one md5
CREATE FUNCTION pg_temp.fn_exec65() RETURNS text LANGUAGE sql VOLATILE AS $h$
  SELECT md5(coalesce(string_agg(p.oid::regprocedure::text || ':' || has_function_privilege('service_role', p.oid, 'EXECUTE')::text || ':'
                                 || has_function_privilege('anon', p.oid, 'EXECUTE')::text || ':' || has_function_privilege('authenticated', p.oid, 'EXECUTE')::text
                                 || ':' || has_function_privilege('public', p.oid, 'EXECUTE')::text || ':' || p.prosecdef::text,
                                 '|' ORDER BY p.oid::regprocedure::text COLLATE "C"), ''))
    FROM pg_catalog.pg_proc p
   WHERE p.pronamespace = 'public'::regnamespace
     AND (p.prosrc ~ '_mcp_r_(get_message|list_deal_messages)' OR EXISTS (SELECT 1 FROM pg_temp.t65_rel x WHERE position(x.name IN p.prosrc) > 0))
$h$;
-- the names of those functions service_role can execute (report only)
CREATE FUNCTION pg_temp.fn_sr65() RETURNS jsonb LANGUAGE sql VOLATILE AS $h$
  SELECT coalesce(jsonb_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '[]')
    FROM pg_catalog.pg_proc p
   WHERE p.pronamespace = 'public'::regnamespace AND has_function_privilege('service_role', p.oid, 'EXECUTE')
     AND (p.prosrc ~ '_mcp_r_(get_message|list_deal_messages)' OR EXISTS (SELECT 1 FROM pg_temp.t65_rel x WHERE position(x.name IN p.prosrc) > 0))
$h$;
CREATE FUNCTION pg_temp.default_acl65() RETURNS text LANGUAGE sql VOLATILE AS $h$
  SELECT md5(coalesce(string_agg(d.defaclrole::regrole::text || ':' || d.defaclnamespace::text || ':' || d.defaclobjtype::text || ':'
                                 || coalesce((SELECT string_agg(x.item::text, ',' ORDER BY x.item::text COLLATE "C") FROM unnest(d.defaclacl) x(item)), ''),
                                 '|' ORDER BY d.defaclrole::regrole::text COLLATE "C", d.defaclnamespace, d.defaclobjtype), ''))
    FROM pg_catalog.pg_default_acl d
$h$;
-- one statement as service_role (claims set, current_user asserted). 'ok', 'ERR <sqlstate>', or 'ROLE <who>' when the
-- role did not change.
CREATE FUNCTION pg_temp.sr_exec65(q text) RETURNS text LANGUAGE plpgsql AS $h$
DECLARE who text;
BEGIN
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('role', 'service_role')::text, true);
    PERFORM set_config('request.jwt.claim.role', 'service_role', true);
    SET LOCAL ROLE service_role;
    who := current_user;
    IF who IS DISTINCT FROM 'service_role' THEN
      RAISE EXCEPTION 'ROLE %', who;
    END IF;
    EXECUTE q;
    RESET ROLE;
    PERFORM pg_temp.clear_claims();
    RETURN 'ok';
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.clear_claims();
    IF SQLERRM LIKE 'ROLE %' THEN RETURN 'ROLE ' || coalesce(who, '?'); END IF;
    RETURN 'ERR ' || SQLSTATE;
  END;
END $h$;
-- every relation of the given blocks still granting service_role something (any type, column, or ACL entry)
CREATE FUNCTION pg_temp.sr_holds65(blocks text[]) RETURNS text[] LANGUAGE plpgsql VOLATILE AS $h$
DECLARE r record; out text[] := '{}';
BEGIN
  FOR r IN SELECT x.name, x.kind, pg_catalog.to_regclass('public.' || x.name) AS oid FROM pg_temp.t65_rel x
            WHERE x.blk = ANY (blocks) ORDER BY x.name COLLATE "C" LOOP
    IF r.oid IS NULL THEN
      out := out || (r.name || ':missing');
    ELSIF pg_temp.sr_acl65(r.name) <> ''
       OR (r.kind = 'S' AND (has_sequence_privilege('service_role', r.oid, 'USAGE') OR has_sequence_privilege('service_role', r.oid, 'SELECT')
                             OR has_sequence_privilege('service_role', r.oid, 'UPDATE')))
       OR (r.kind = 'r' AND (EXISTS (SELECT 1 FROM unnest(pg_temp.privs65()) p WHERE has_table_privilege('service_role', r.oid, p))
                             OR has_any_column_privilege('service_role', r.oid, 'SELECT, INSERT, UPDATE, REFERENCES'))) THEN
      out := out || r.name;
    END IF;
  END LOOP;
  RETURN out;
END $h$;
-- SELECT, INSERT, UPDATE and DELETE (each matching no row) as service_role on every table of the given blocks; the
-- statements that did not end in 42501, as table:statement=result
CREATE FUNCTION pg_temp.sr_statements65(blocks text[]) RETURNS text[] LANGUAGE plpgsql VOLATILE AS $h$
DECLARE r record; col text; q text; res text; out text[] := '{}';
BEGIN
  FOR r IN SELECT x.name, pg_catalog.to_regclass('public.' || x.name) AS oid FROM pg_temp.t65_rel x
            WHERE x.blk = ANY (blocks) AND x.kind = 'r' ORDER BY x.name COLLATE "C" LOOP
    col := (SELECT quote_ident(a.attname) FROM pg_catalog.pg_attribute a
             WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped AND a.attidentity = '' AND a.attgenerated = ''
             ORDER BY a.attnum LIMIT 1);
    FOREACH q IN ARRAY ARRAY[format('SELECT count(*) FROM public.%I', r.name),
                             format('INSERT INTO public.%I OVERRIDING SYSTEM VALUE SELECT * FROM public.%I WHERE false', r.name, r.name),
                             format('UPDATE public.%I SET %s = %s WHERE false', r.name, col, col),
                             format('DELETE FROM public.%I WHERE false', r.name)] LOOP
      res := pg_temp.sr_exec65(q);
      IF res IS DISTINCT FROM 'ERR 42501' THEN
        out := out || (r.name || ':' || split_part(q, ' ', 1) || '=' || res);
      END IF;
    END LOOP;
  END LOOP;
  RETURN out;
END $h$;
-- rows of the A, B and C tables and auth.users that existed before the fixtures. Left out: mcp_settings (the fixtures
-- set its one row for this call), mcp_rate_counters (a tool call deletes counter windows older than one day, of any
-- bucket), and mcp_authorization_requests rows already expired. auth.users is hashed on id, email and created_at only:
-- a sign-in writes other columns of the row.
CREATE FUNCTION pg_temp.row_hashes65() RETURNS TABLE (t text, h text) LANGUAGE sql VOLATILE AS $h$
  SELECT 'cloud_deal_messages'::text, md5(x::text) FROM public.cloud_deal_messages x
  UNION ALL SELECT 'cloud_deal_files', md5(x::text) FROM public.cloud_deal_files x
  UNION ALL SELECT 'cloud_blobs', md5(x::text) FROM public.cloud_blobs x
  UNION ALL SELECT 'mcp_redirect_allowlist', md5(x::text) FROM public.mcp_redirect_allowlist x
  UNION ALL SELECT 'mcp_oauth_clients', md5(x::text) FROM public.mcp_oauth_clients x
  UNION ALL SELECT 'mcp_authorization_requests', md5(x::text) FROM public.mcp_authorization_requests x WHERE x.expires_at >= now()
  UNION ALL SELECT 'mcp_connections', md5(x::text) FROM public.mcp_connections x
  UNION ALL SELECT 'mcp_authorization_codes', md5(x::text) FROM public.mcp_authorization_codes x
  UNION ALL SELECT 'mcp_tokens', md5(x::text) FROM public.mcp_tokens x
  UNION ALL SELECT 'mcp_call_log', md5(x::text) FROM public.mcp_call_log x
  UNION ALL SELECT 'cloud_deals', md5(x::text) FROM public.cloud_deals x
  UNION ALL SELECT 'cloud_deal_parties', md5(x::text) FROM public.cloud_deal_parties x
  UNION ALL SELECT 'cloud_deal_checklists', md5(x::text) FROM public.cloud_deal_checklists x
  UNION ALL SELECT 'cloud_deal_checklist_items', md5(x::text) FROM public.cloud_deal_checklist_items x
  UNION ALL SELECT 'cloud_autosave_settings', md5(x::text) FROM public.cloud_autosave_settings x
  UNION ALL SELECT 'member_addons', md5(x::text) FROM public.member_addons x
  UNION ALL SELECT 'auth.users', md5(concat_ws('|', x.id::text, x.email::text, x.created_at::text)) FROM auth.users x
$h$;
CREATE TEMP TABLE t65_pre ON COMMIT DROP AS SELECT * FROM pg_temp.row_hashes65();
CREATE FUNCTION pg_temp.foreign_rows65() RETURNS jsonb LANGUAGE sql VOLATILE AS $h$
  WITH now_ AS (SELECT * FROM pg_temp.row_hashes65()),
       tbls(t) AS (VALUES ('cloud_deal_messages'), ('cloud_deal_files'), ('cloud_blobs'), ('mcp_redirect_allowlist'), ('mcp_oauth_clients'),
                          ('mcp_authorization_requests'), ('mcp_connections'), ('mcp_authorization_codes'), ('mcp_tokens'), ('mcp_call_log'),
                          ('cloud_deals'), ('cloud_deal_parties'), ('cloud_deal_checklists'), ('cloud_deal_checklist_items'),
                          ('cloud_autosave_settings'), ('member_addons'), ('auth.users'))
  SELECT jsonb_object_agg(b.t, jsonb_build_object(
           'gone_or_changed', (SELECT count(*) FROM pg_temp.t65_pre p WHERE p.t = b.t AND NOT EXISTS (SELECT 1 FROM now_ n WHERE n.t = p.t AND n.h = p.h))))
    FROM tbls b
$h$;
-- result reducers: a call_as answer is either a JSON value or 'ERR <sqlstate> <message>'; only the SQLSTATE is kept
CREATE FUNCTION pg_temp.state65(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $h$
  SELECT CASE WHEN jsonb_typeof(v) = 'string' AND (v #>> '{}') LIKE 'ERR %' THEN split_part(v #>> '{}', ' ', 2) END
$h$;
CREATE FUNCTION pg_temp.short65(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$
  SELECT CASE WHEN t ~ '^("[a-z_]+"|[0-9]+)$' THEN t WHEN t LIKE 'ERR %' THEN 'ERR ' || split_part(t, ' ', 2) ELSE 'other' END
$h$;
-- the sorted top-level keys of a JSON object (no values)
CREATE FUNCTION pg_temp.keys65(v jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $h$
  SELECT CASE WHEN jsonb_typeof(v) = 'object' THEN (SELECT coalesce(jsonb_agg(k ORDER BY k), '[]') FROM jsonb_object_keys(v) k) END
$h$;

DO $t0_4265$ BEGIN PERFORM pg_temp.rec('t_fixture_start', to_jsonb(clock_timestamp())); END $t0_4265$;
-- BACKLOG-4263 P9 harness fixtures. Users A and B: licensed through one invented organization on the team plan, Keepr
-- Cloud on (notice 1). Rows come from the real producers (cloud_upsert_deal, cloud_upsert_messages, cloud_upsert_files,
-- cloud_tombstone, cloud_delete_deal, cloud_claim_install, set_my_cloud_autosave). Set directly, each named here:
--   cloud_release_switches (one row): messages_upload on, one_computer off while the second computer's deal is saved,
--     then on (the coordinator's release UPDATE);
--   one message's link_state set to 'suggested': the value the 20261123100000 writer gives a row sent with
--     link_origin 'review_queue' (/*MSG:linkstate*/); 20261123130000 refuses such rows (plan P4 condition 2), so this
--     row stands for one written before it;
--   mcp_settings (one row): enabled and the fixture portal secret in portal_secret_prev_sha256, for this call only;
--   mcp_oauth_clients, mcp_connections and mcp_tokens rows of three invented connections (approval-page version 1 or 2;
--     no producer exists until 20261123150000 sets the approval page to version 2).
DO $fx4263t$
DECLARE A uuid; B uuid; O uuid; r jsonb; big text; who jsonb; rows jsonb; k text; n int; sweep record;
BEGIN
  PERFORM pg_temp.put('RUN', gen_random_uuid());
  A := pg_temp.put('A', gen_random_uuid());
  B := pg_temp.put('B', gen_random_uuid());
  O := pg_temp.put('O', gen_random_uuid());
  FOREACH k IN ARRAY ARRAY['IA', 'IB', 'IBB'] LOOP PERFORM pg_temp.put(k, gen_random_uuid()); END LOOP;
  SET LOCAL session_replication_role = replica;
  INSERT INTO auth.users (id, email, aud, role, instance_id, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
  SELECT pg_temp.f(x), 'p4263t-' || left(pg_temp.s('RUN'), 8) || '-' || lower(x) || '@example.test', 'authenticated', 'authenticated',
         '00000000-0000-0000-0000-000000000000', '{"provider":"email"}', '{}', now(), now()
    FROM unnest(ARRAY['A', 'B']) x;
  INSERT INTO public.users (id, email, oauth_provider, oauth_id, display_name)
  SELECT pg_temp.f(x), 'p4263t-' || left(pg_temp.s('RUN'), 8) || '-' || lower(x) || '@example.test', 'email', pg_temp.s(x), 'Fixture t ' || x
    FROM unnest(ARRAY['A', 'B']) x
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO public.organizations (id, name, slug) VALUES (O, 'Fixture t', 'p4263t-' || left(pg_temp.s('RUN'), 12));
  INSERT INTO public.organization_members (id, organization_id, user_id, role, license_status)
  VALUES (gen_random_uuid(), O, A, 'agent', 'active'), (gen_random_uuid(), O, B, 'agent', 'active');
  INSERT INTO public.organization_plans (organization_id, plan_id, feature_overrides)
  VALUES (O, (SELECT id FROM public.plans WHERE tier = 'team' ORDER BY sort_order, name LIMIT 1), '{"cloud_autosave_assignable":{"enabled":true}}');
  SET LOCAL session_replication_role = origin;
  UPDATE public.cloud_release_switches SET one_computer = false, messages_upload = true WHERE id;
  FOREACH k IN ARRAY ARRAY['A', 'B'] LOOP
    r := pg_temp.j(pg_temp.call_as(NULL, format('SELECT public.assign_member_addon(%L::uuid, %L::uuid, %L, true, NULL::timestamptz)', O, pg_temp.f(k), 'cloud_autosave'), 'service_role'));
    IF r ->> 'state' IS DISTINCT FROM 'assigned' THEN RAISE EXCEPTION 'FIXTURE assign % failed: %', k, r; END IF;
    r := pg_temp.as_user(k, 'set_my_cloud_autosave', '%L::uuid, %L::boolean, %L::integer, %L::uuid', pg_temp.s(k), 'true', '1', NULL);
    IF r ->> 'success' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'FIXTURE enable % failed: %', k, r; END IF;
  END LOOP;

  -- deals: dA, dBig, dSw (A, computer IA); dU unconfirmed, dR removed (IA); dB (A, computer IB); dBB (B)
  PERFORM pg_temp.deal('A', 'IA', 'dA', 'active');
  PERFORM pg_temp.deal('A', 'IA', 'dBig', 'active');
  PERFORM pg_temp.deal('A', 'IA', 'dSw', 'active');
  PERFORM pg_temp.deal('A', 'IA', 'dU', 'rejected');
  PERFORM pg_temp.deal('A', 'IA', 'dR', 'active');
  PERFORM pg_temp.deal('A', 'IB', 'dB', 'active');
  PERFORM pg_temp.deal('B', 'IBB', 'dBB', 'active');
  IF (SELECT is_confirmed FROM public.cloud_deals WHERE id = pg_temp.f('dU')) IS NOT FALSE THEN RAISE EXCEPTION 'FIXTURE dU is confirmed'; END IF;

  who := '{"from":"Seller Agent <seller@example.test>","to":["buyer@example.test","agent@example.test"],"cc":["tc@example.test"]}';
  PERFORM pg_temp.msgs('A', 'IA', 'dA', jsonb_build_array(
    pg_temp.mrow('m_lin', 'email', 'Offer accepted', E'Line 1\nLine 2', who, '2026-01-01T10:00:00.000Z', NULL, NULL, false, 'thr-lin'),
    pg_temp.mrow('m_rev', 'email', 'Inspection', 'Contact-only match', who, '2026-01-03T10:00:00.000Z', NULL, 'address_missing', false, 'thr-rev'),
    pg_temp.mrow('m_txt', 'text', NULL, 'See you at closing', '{"from":"+15555550100","to":["me"]}', '2026-01-04T10:00:00.000Z', NULL, NULL, true, 'chat-p4263t'),
    pg_temp.mrow('m_recv', 'email', 'No send time', 'Received only', who, NULL, '2026-01-02T12:00:00.000Z', NULL, false, 'thr-recv'),
    pg_temp.mrow('m_none', 'email', 'No times', 'No send or receive time', who, NULL, NULL, NULL, false, 'thr-none'),
    pg_temp.mrow('m_tomb', 'email', 'Unlinked later', 'Removed body', who, '2026-01-05T10:00:00.000Z', NULL, NULL, false, 'thr-tomb'),
    pg_temp.mrow('m_sug', 'email', 'Suggested', 'Suggested body', who, '2026-01-06T10:00:00.000Z', NULL, NULL, false, 'thr-sug')));
  PERFORM pg_temp.files('A', 'IA', 'dA', jsonb_build_array(
    pg_temp.frow('f_lin1', 'm_lin', 'Contract.pdf', 'application/pdf', 'too_large'),
    pg_temp.frow('f_lin2', 'm_lin', 'Photo.jpg', 'image/jpeg', 'no_local_file'),
    pg_temp.frow('f_lin3', 'm_lin', 'Removed.pdf', 'application/pdf', 'too_large'),
    pg_temp.frow('f_deal', NULL, 'Deal level.pdf', 'application/pdf', 'too_large'),
    pg_temp.frow('f_tomb', 'm_tomb', 'Of removed message.pdf', 'application/pdf', 'too_large')));
  r := pg_temp.tomb('A', 'IA', 'message', ARRAY[pg_temp.f('m_tomb')]);
  IF r -> 'results' -> 0 ->> 'status' IS DISTINCT FROM 'removed' THEN RAISE EXCEPTION 'FIXTURE tombstone message failed: %', r; END IF;
  r := pg_temp.tomb('A', 'IA', 'file', ARRAY[pg_temp.f('f_lin3')]);
  IF r -> 'results' -> 0 ->> 'status' IS DISTINCT FROM 'removed' THEN RAISE EXCEPTION 'FIXTURE tombstone file failed: %', r; END IF;
  UPDATE public.cloud_deal_messages SET link_state = 'suggested' WHERE id = pg_temp.f('m_sug');
  PERFORM pg_temp.msgs('A', 'IA', 'dU', jsonb_build_array(pg_temp.mrow('m_unc', 'email', 'Unconfirmed deal', 'x', who, '2026-01-01T10:00:00.000Z', NULL, NULL, false, 't')));
  PERFORM pg_temp.msgs('A', 'IA', 'dR', jsonb_build_array(pg_temp.mrow('m_rem', 'email', 'Removed deal', 'x', who, '2026-01-01T10:00:00.000Z', NULL, NULL, false, 't')));
  r := pg_temp.as_user('A', 'cloud_delete_deal', '%L::uuid, %L::uuid', pg_temp.s('A'), pg_temp.s('dR'));
  IF r ->> 'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'FIXTURE delete deal failed: %', r; END IF;
  PERFORM pg_temp.msgs('A', 'IB', 'dB', jsonb_build_array(pg_temp.mrow('m_inact', 'email', 'Other computer', 'x', who, '2026-01-01T10:00:00.000Z', NULL, NULL, false, 't')));
  PERFORM pg_temp.msgs('B', 'IBB', 'dBB', jsonb_build_array(pg_temp.mrow('m_bb', 'email', 'Another person', 'x', who, '2026-01-01T10:00:00.000Z', NULL, NULL, false, 't')));

  -- two messages at every cap: a 1,000,000-character subject, 1 + 1000 + 10 participants of 400 four-byte characters
  -- each, 500 files with 300-character names and 200-character types; m_big1's body is 1,000,000 characters of quotes,
  -- newlines, control characters, four-byte and two-byte characters
  big := left(repeat('a"' || E'\n' || chr(1) || chr(128512) || chr(233), 166667), 1000000);
  INSERT INTO pg_temp.t_txt VALUES ('big1_md5', md5(public._mcp_strip(big)));
  who := jsonb_build_object('from', repeat(chr(128512), 400),
                            'to', (SELECT jsonb_agg(repeat(chr(128512), 399) || g) FROM generate_series(1, 1000) g),
                            'cc', (SELECT jsonb_agg(repeat(chr(128512), 399) || g) FROM generate_series(1, 10) g));
  PERFORM pg_temp.msgs('A', 'IA', 'dBig', jsonb_build_array(
    pg_temp.mrow('m_big1', 'email', repeat(chr(128512) || 'x', 500000), big, who, '2026-02-01T10:00:00.000Z', NULL, NULL, false, repeat(chr(128512), 3000)),
    pg_temp.mrow('m_big2', 'email', repeat(chr(128512) || 'x', 500000), 'short', who, '2026-02-02T10:00:00.000Z', NULL, NULL, false, repeat(chr(128512), 3000))));
  IF (SELECT char_length(body_text) FROM public.cloud_deal_messages WHERE id = pg_temp.f('m_big1')) <> 1000000 THEN
    RAISE EXCEPTION 'FIXTURE m_big1 body was cut';
  END IF;
  FOREACH k IN ARRAY ARRAY['m_big1', 'm_big2'] LOOP
    PERFORM pg_temp.files('A', 'IA', 'dBig', (SELECT jsonb_agg(pg_temp.frow(k || '_f' || g, k, repeat(chr(128512), 300), repeat(chr(128512), 200), 'too_large'))
                                               FROM generate_series(1, 500) g));
  END LOOP;

  -- body sizes at a part boundary (budget 60000 bytes for these small answers): 1 part, then 2 parts
  FOR sweep IN SELECT * FROM (VALUES ('s_a1', 'a', 60000), ('s_a2', 'a', 60001), ('s_q1', '"', 30000), ('s_q2', '"', 30001),
                                     ('s_e1', chr(128512), 15000), ('s_e2', chr(128512), 15001), ('s_t1', chr(9), 30000), ('s_t2', chr(9), 30001)) x(k, ch, n) LOOP
    PERFORM pg_temp.msgs('A', 'IA', 'dSw', jsonb_build_array(pg_temp.mrow(sweep.k, 'email', NULL, repeat(sweep.ch, sweep.n), NULL, '2026-03-01T10:00:00.000Z', NULL, NULL, false, 't')));
  END LOOP;

  -- a body with invisible characters (tag characters U+E0041..U+E005A and U+202E), and a message whose 'from' is an
  -- array of three addresses
  PERFORM pg_temp.msgs('A', 'IA', 'dSw', jsonb_build_array(
    pg_temp.mrow('m_inv', 'email', 'Invisible', 'Visible start ' || (SELECT string_agg(chr(c), '' ORDER BY c) FROM generate_series(917569, 917594) c) || chr(8238) || ' visible end',
                 NULL, '2026-03-02T10:00:00.000Z', NULL, NULL, false, 't'),
    pg_temp.mrow('m_from', 'email', 'Many senders', 'x', '{"from":["a@example.test","b@example.test","c@example.test"],"to":["d@example.test"],"cc":["e@example.test"]}',
                 '2026-03-03T10:00:00.000Z', NULL, NULL, false, 't')));

  -- MCP: switched on, the fixture portal secret, connections K1 (A, approval page 1), K2 (A, page 2), KB2 (B, page 2)
  UPDATE public.mcp_settings SET portal_secret_prev_sha256 = sha256(convert_to(pg_temp.secret(), 'UTF8')), enabled = true WHERE id;
  INSERT INTO public.mcp_oauth_clients (client_id, client_name, redirect_uris, ip_sha256)
  VALUES (pg_temp.client(), 'Fixture app', ARRAY['https://claude.ai/api/mcp/auth_callback'], sha256(convert_to('p4263t-ip', 'UTF8')));
  PERFORM pg_temp.conn('K1', A, 1);
  PERFORM pg_temp.conn('K2', A, 2);
  PERFORM pg_temp.conn('KB2', B, 2);

  -- one computer per account on; A's active computer is IA, B's is IBB
  UPDATE public.cloud_release_switches SET one_computer = true WHERE id;
  r := pg_temp.claim('A', 'IA', false);
  IF r ->> 'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'FIXTURE claim A failed: %', r; END IF;
  r := pg_temp.claim('B', 'IBB', false);
  IF r ->> 'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'FIXTURE claim B failed: %', r; END IF;
  PERFORM pg_temp.rec('fx_counts', jsonb_build_object(
    'A_messages', (SELECT count(*) FROM public.cloud_deal_messages WHERE owner_user_id = A),
    'A_files', (SELECT count(*) FROM public.cloud_deal_files WHERE owner_user_id = A),
    'A_active_is_IA', (SELECT active_install_id = pg_temp.f('IA') FROM public.cloud_autosave_settings WHERE user_id = A)));
END
$fx4263t$;

INSERT INTO pg_temp.t65_txt VALUES ('migration', $t1$-- ============================================================================
-- Migration: revokes all privileges of role service_role on 18 tables and 1 sequence (BACKLOG-4265)
--
-- Tables:
--   cloud_deal_messages, cloud_deal_files, cloud_blobs
--   mcp_settings, mcp_redirect_allowlist, mcp_oauth_clients, mcp_authorization_requests, mcp_connections,
--   mcp_authorization_codes, mcp_tokens, mcp_rate_counters, mcp_call_log
--   cloud_deals, cloud_deal_parties, cloud_deal_checklists, cloud_deal_checklist_items, cloud_autosave_settings,
--   member_addons
-- Sequence: public.mcp_call_log_id_seq (the identity sequence of public.mcp_call_log.id).
-- Privileges of every other role (anon, authenticated, PUBLIC, mcp_reader, the owner) are unchanged; the post-check
--   compares them with a fingerprint the pre-check takes in this transaction.
-- No function, policy, default privilege, storage object or row is changed.
-- Pre-check (refuses, nothing applied): current_user is postgres; each relation exists, is owned by postgres and has the
--   expected kind; mcp_call_log_id_seq is the identity sequence of mcp_call_log.id; every ACL entry for service_role on
--   these relations has grantor postgres (the owner).
-- Post-check (refuses, nothing applied): on each relation service_role holds no table privilege of any type (MAINTAIN
--   included on PostgreSQL 17 and later), no column privilege and no ACL entry; no sequence privilege on the sequence;
--   the other roles' ACL entries (table and column) equal the pre-check fingerprint.
-- Locks: lock_timeout 3s is the first statement; if a lock is not obtained in 3 seconds nothing is applied. The lock
--   mode of the privilege change is not measured here (supabase/tests/backlog-4265/README.md).
-- Re-runnable: a second run finds no service_role entry, changes nothing and passes both checks.
-- Deploy order: after 20261123130000.
-- Rollback: supabase/tests/backlog-4265/rollback-20261123160000.sql
