$pre4265r$;

-- tables: cloud_deal_messages, cloud_deal_files, cloud_blobs
GRANT SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER, MAINTAIN ON TABLE public.cloud_deal_messages, public.cloud_deal_files, public.cloud_blobs TO service_role;
-- tables: mcp_settings, mcp_redirect_allowlist, mcp_oauth_clients, mcp_authorization_requests, mcp_connections, mcp_authorization_codes, mcp_tokens, mcp_rate_counters, mcp_call_log
GRANT SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER, MAINTAIN ON TABLE public.mcp_settings, public.mcp_redirect_allowlist, public.mcp_oauth_clients, public.mcp_authorization_requests, public.mcp_connections, public.mcp_authorization_codes, public.mcp_tokens, public.mcp_rate_counters, public.mcp_call_log TO service_role;
-- sequence: mcp_call_log_id_seq
GRANT USAGE, SELECT, UPDATE ON SEQUENCE public.mcp_call_log_id_seq TO service_role;
-- tables: cloud_deals, cloud_deal_parties, cloud_deal_checklists, cloud_deal_checklist_items, cloud_autosave_settings, member_addons
GRANT SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER, MAINTAIN ON TABLE public.cloud_deals, public.cloud_deal_parties, public.cloud_deal_checklists, public.cloud_deal_checklist_items, public.cloud_autosave_settings, public.member_addons TO service_role;

DELETE FROM supabase_migrations.schema_migrations WHERE version = '20261123160000';

DO $post4265r$
DECLARE v text;
BEGIN
  SELECT string_agg(x.name, ',' ORDER BY x.name) INTO v
    FROM (VALUES ('cloud_deal_messages', 'r'), ('cloud_deal_files', 'r'), ('cloud_blobs', 'r'), ('mcp_settings', 'r'), ('mcp_redirect_allowlist', 'r'), ('mcp_oauth_clients', 'r'), ('mcp_authorization_requests', 'r'), ('mcp_connections', 'r'), ('mcp_authorization_codes', 'r'), ('mcp_tokens', 'r'), ('mcp_rate_counters', 'r'), ('mcp_call_log', 'r'), ('cloud_deals', 'r'), ('cloud_deal_parties', 'r'), ('cloud_deal_checklists', 'r'), ('cloud_deal_checklist_items', 'r'), ('cloud_autosave_settings', 'r'), ('member_addons', 'r'), ('mcp_call_log_id_seq', 'S')) x(name, kind)
   WHERE (SELECT coalesce(string_agg(pg_catalog.pg_get_userbyid(a.grantor)::text || ':' || a.privilege_type || ':' || a.is_grantable::text, ','
                                     ORDER BY a.privilege_type COLLATE "C", pg_catalog.pg_get_userbyid(a.grantor)::text COLLATE "C"), '')
            FROM pg_catalog.pg_class c, aclexplode(c.relacl) a
           WHERE c.oid = pg_catalog.to_regclass('public.' || x.name) AND a.grantee = 'service_role'::regrole)
         IS DISTINCT FROM CASE x.kind WHEN 'S' THEN 'postgres:SELECT:false,postgres:UPDATE:false,postgres:USAGE:false' ELSE 'postgres:DELETE:false,postgres:INSERT:false,postgres:MAINTAIN:false,postgres:REFERENCES:false,postgres:SELECT:false,postgres:TRIGGER:false,postgres:TRUNCATE:false,postgres:UPDATE:false' END;
  IF v IS NOT NULL THEN
    RAISE EXCEPTION 'ROLLBACK POST-CHECK 20261123160000 FAILED, nothing changed: service_role items differ on %', v;
  END IF;
  IF (SELECT md5(coalesce(string_agg(z.s, '|' ORDER BY z.s COLLATE "C"), '')) FROM (
      SELECT c.relname::text || '::' || CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee)::text END || ':'
             || pg_catalog.pg_get_userbyid(a.grantor)::text || ':' || a.privilege_type || ':' || a.is_grantable::text AS s
        FROM pg_catalog.pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
       WHERE c.relnamespace = 'public'::regnamespace AND c.relname = ANY (ARRAY['cloud_deal_messages', 'cloud_deal_files', 'cloud_blobs', 'mcp_settings', 'mcp_redirect_allowlist', 'mcp_oauth_clients', 'mcp_authorization_requests', 'mcp_connections', 'mcp_authorization_codes', 'mcp_tokens', 'mcp_rate_counters', 'mcp_call_log', 'cloud_deals', 'cloud_deal_parties', 'cloud_deal_checklists', 'cloud_deal_checklist_items', 'cloud_autosave_settings', 'member_addons', 'mcp_call_log_id_seq']) AND a.grantee IS DISTINCT FROM 'service_role'::regrole
      UNION ALL
      SELECT c.relname::text || ':' || t.attname::text || ':' || CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee)::text END || ':'
             || pg_catalog.pg_get_userbyid(a.grantor)::text || ':' || a.privilege_type || ':' || a.is_grantable::text
        FROM pg_catalog.pg_class c JOIN pg_catalog.pg_attribute t ON t.attrelid = c.oid AND t.attnum > 0 AND NOT t.attisdropped
        CROSS JOIN LATERAL aclexplode(t.attacl) a
       WHERE c.relnamespace = 'public'::regnamespace AND c.relname = ANY (ARRAY['cloud_deal_messages', 'cloud_deal_files', 'cloud_blobs', 'mcp_settings', 'mcp_redirect_allowlist', 'mcp_oauth_clients', 'mcp_authorization_requests', 'mcp_connections', 'mcp_authorization_codes', 'mcp_tokens', 'mcp_rate_counters', 'mcp_call_log', 'cloud_deals', 'cloud_deal_parties', 'cloud_deal_checklists', 'cloud_deal_checklist_items', 'cloud_autosave_settings', 'member_addons', 'mcp_call_log_id_seq']) AND a.grantee IS DISTINCT FROM 'service_role'::regrole) z) IS DISTINCT FROM current_setting('keepr.r4265_other_acl', true) THEN
    RAISE EXCEPTION 'ROLLBACK POST-CHECK 20261123160000 FAILED, nothing changed: items of other roles changed';
  END IF;
  IF (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261123160000') <> 0 THEN
    RAISE EXCEPTION 'ROLLBACK POST-CHECK 20261123160000 FAILED, nothing changed: ledger row kept';
  END IF;
END
$post4265r$;
$t2$),
  ('precheck', $t3$DO $pre4265$
DECLARE
  r record;
  v_bad text := '';
  v_fp text;
BEGIN
  IF current_user IS DISTINCT FROM 'postgres' THEN
    RAISE EXCEPTION '4265 pre-check: current_user is %, not postgres', current_user;
  END IF;
  FOR r IN
    SELECT x.name, x.kind, c.oid, c.relkind, pg_catalog.pg_get_userbyid(c.relowner) AS owner
      FROM (VALUES ('cloud_deal_messages', 'r'), ('cloud_deal_files', 'r'), ('cloud_blobs', 'r'),
                   ('mcp_settings', 'r'), ('mcp_redirect_allowlist', 'r'), ('mcp_oauth_clients', 'r'),
                   ('mcp_authorization_requests', 'r'), ('mcp_connections', 'r'), ('mcp_authorization_codes', 'r'),
                   ('mcp_tokens', 'r'), ('mcp_rate_counters', 'r'), ('mcp_call_log', 'r'),
                   ('cloud_deals', 'r'), ('cloud_deal_parties', 'r'), ('cloud_deal_checklists', 'r'),
                   ('cloud_deal_checklist_items', 'r'), ('cloud_autosave_settings', 'r'), ('member_addons', 'r'),
                   ('mcp_call_log_id_seq', 'S')) x(name, kind)
      LEFT JOIN pg_catalog.pg_class c ON c.oid = pg_catalog.to_regclass('public.' || x.name)
  LOOP
    IF r.oid IS NULL THEN
      v_bad := v_bad || r.name || ' missing; ';
    ELSIF r.relkind::text IS DISTINCT FROM r.kind THEN
      v_bad := v_bad || r.name || ' kind ' || r.relkind::text || '; ';
    ELSIF r.owner IS DISTINCT FROM 'postgres' THEN
      v_bad := v_bad || r.name || ' owner ' || r.owner || '; ';
    ELSIF EXISTS (SELECT 1 FROM pg_catalog.pg_class c, aclexplode(c.relacl) a
                   WHERE c.oid = r.oid AND a.grantee = 'service_role'::regrole AND a.grantor IS DISTINCT FROM c.relowner) THEN
      v_bad := v_bad || r.name || ' ACL entry for service_role has grantor '
               || (SELECT string_agg(DISTINCT pg_catalog.pg_get_userbyid(a.grantor), ',') FROM pg_catalog.pg_class c, aclexplode(c.relacl) a
                    WHERE c.oid = r.oid AND a.grantee = 'service_role'::regrole AND a.grantor IS DISTINCT FROM c.relowner) || '; ';
    END IF;
  END LOOP;
  IF pg_catalog.pg_get_serial_sequence('public.mcp_call_log', 'id') IS DISTINCT FROM 'public.mcp_call_log_id_seq' THEN
    v_bad := v_bad || 'identity sequence of mcp_call_log.id is ' || coalesce(pg_catalog.pg_get_serial_sequence('public.mcp_call_log', 'id'), 'none') || '; ';
  END IF;
  IF v_bad <> '' THEN
    RAISE EXCEPTION '4265 pre-check: %', v_bad;
  END IF;
  SELECT md5(coalesce(string_agg(z.s, '|' ORDER BY z.s COLLATE "C"), '')) INTO v_fp
    FROM (SELECT c.relname::text || '::'
                 || CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee)::text END || ':'
                 || pg_catalog.pg_get_userbyid(a.grantor)::text || ':' || a.privilege_type || ':' || a.is_grantable::text AS s
            FROM pg_catalog.pg_class c
            CROSS JOIN LATERAL aclexplode(c.relacl) a
           WHERE c.relnamespace = 'public'::regnamespace AND a.grantee IS DISTINCT FROM 'service_role'::regrole
             AND c.relname IN ('cloud_deal_messages', 'cloud_deal_files', 'cloud_blobs', 'mcp_settings', 'mcp_redirect_allowlist',
                               'mcp_oauth_clients', 'mcp_authorization_requests', 'mcp_connections', 'mcp_authorization_codes',
                               'mcp_tokens', 'mcp_rate_counters', 'mcp_call_log', 'cloud_deals', 'cloud_deal_parties',
                               'cloud_deal_checklists', 'cloud_deal_checklist_items', 'cloud_autosave_settings', 'member_addons',
                               'mcp_call_log_id_seq')
          UNION ALL
          SELECT c.relname::text || ':' || t.attname::text || ':'
                 || CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee)::text END || ':'
                 || pg_catalog.pg_get_userbyid(a.grantor)::text || ':' || a.privilege_type || ':' || a.is_grantable::text
            FROM pg_catalog.pg_class c
            JOIN pg_catalog.pg_attribute t ON t.attrelid = c.oid AND t.attnum > 0 AND NOT t.attisdropped
            CROSS JOIN LATERAL aclexplode(t.attacl) a
           WHERE c.relnamespace = 'public'::regnamespace AND a.grantee IS DISTINCT FROM 'service_role'::regrole
             AND c.relname IN ('cloud_deal_messages', 'cloud_deal_files', 'cloud_blobs', 'mcp_settings', 'mcp_redirect_allowlist',
                               'mcp_oauth_clients', 'mcp_authorization_requests', 'mcp_connections', 'mcp_authorization_codes',
                               'mcp_tokens', 'mcp_rate_counters', 'mcp_call_log', 'cloud_deals', 'cloud_deal_parties',
                               'cloud_deal_checklists', 'cloud_deal_checklist_items', 'cloud_autosave_settings', 'member_addons')) z;
  PERFORM set_config('keepr.m4265_other_acl', v_fp, true);
END
$pre4265$;$t3$);
DO $fxend4265$
BEGIN
  PERFORM pg_temp.rec('lock_probe', current_setting('keepr.h4265_probe', true)::jsonb);
  PERFORM pg_temp.rec('t_fixture_end', to_jsonb(clock_timestamp()));
  PERFORM pg_temp.rec('fx_users', to_jsonb((SELECT count(*) FROM auth.users WHERE id IN (pg_temp.f('A'), pg_temp.f('B')))));
  PERFORM pg_temp.rec('fx_m_inact', to_jsonb((SELECT count(*) FROM public.cloud_deal_messages WHERE id = pg_temp.f('m_inact') AND removed_at IS NULL)));
  PERFORM pg_temp.rec('fx_k2', to_jsonb((SELECT count(*) FROM public.mcp_connections WHERE id = pg_temp.f('K2') AND notice_version = 2)));
  PERFORM pg_temp.rec('fx_texts', to_jsonb((SELECT count(*) FROM pg_temp.t65_txt)));
END
$fxend4265$;
DO $fxraise4265$
BEGIN
  PERFORM pg_temp.rec('foreign_rows', pg_temp.foreign_rows65());
  RAISE EXCEPTION 'H4265_FIXTURES %', (SELECT jsonb_object_agg(k, v) FROM pg_temp.t_out);
END
$fxraise4265$;
